import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

const Explore = () => {
  const [users, setUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/users');
      setUsers(res.data);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  const filteredUsers = users.filter(u =>
    u.username.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getProfilePic = (user) => {
    return user?.profilePicture 
      ? `http://localhost:5000${user.profilePicture}` 
      : 'https://ui-avatars.com/api/?name=' + encodeURIComponent(user?.name || user?.username || 'U') + '&background=1877f2&color=fff&size=56';
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="explore-container">
      <h2>🔍 Explore Users</h2>
      <input
        type="text"
        placeholder="Search users..."
        className="search-input"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      <div className="users-grid">
        {filteredUsers.length === 0 ? (
          <p>No users found</p>
        ) : (
          filteredUsers.map(u => (
            <Link to={`/profile/${u._id}`} key={u._id} className="explore-user-card">
              <img 
                src={getProfilePic(u)} 
                alt={u.username}
                onError={(e) => {
                  e.target.src = 'https://ui-avatars.com/api/?name=' + encodeURIComponent(u.name || u.username) + '&background=1877f2&color=fff&size=56';
                }}
              />
              <div>
                <strong>{u.name || u.username}</strong>
                <p>@{u.username} • {u.followers?.length || 0} followers</p>
              </div>
            </Link>
          ))
        )}
      </div>
    </div>
  );
};

export default Explore;
